"""Lower a Kernel to a self-contained C program around one inline-asm loop.

The harness builds two random pointer-chase chains, times `reps` runs of `iters` iterations and
prints `rep r cycles_per_iter X` per rep plus the clock probe. ISA modules subclass `Emitter`;
`emit_c` fills the template, `run_args` builds argv and `parse_output` reads the result.
"""

import re

from ..kernels import Kernel, Op
from . import RunResult

C_TEMPLATE = r"""
/* generated by uarch-re: {name} */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

{cycle_counter}

#define LINE {line}

/* Random cyclic pointer chase over cache lines (Sattolo); each line's first
   word points to the next. No memset and no modulo: under gem5, chain setup
   would otherwise cost more simulated time than the measurement. */
static void *build_chain(size_t bytes, uint32_t seed) {{
    size_t n = bytes / LINE;
    char *buf = NULL;
    if (posix_memalign((void **)&buf, 4096, bytes)) {{ perror("alloc"); exit(1); }}
    size_t *perm = malloc(n * sizeof(size_t));
    for (size_t i = 0; i < n; i++) perm[i] = i;
    uint64_t s = seed | 1;
    for (size_t i = n - 1; i > 0; i--) {{
        s ^= s << 13; s ^= s >> 7; s ^= s << 17;
        size_t j = (size_t)(((unsigned __int128)s * i) >> 64);   /* uniform in [0, i) */
        size_t t = perm[i]; perm[i] = perm[j]; perm[j] = t;
    }}
    for (size_t i = 0; i < n; i++) {{
        size_t next = (i + 1 == n) ? 0 : i + 1;
        *(void **)(buf + perm[i] * LINE) = buf + perm[next] * LINE;
    }}
    free(perm);
    return buf;
}}

/* Counter ticks per dependent add (latency 1): ~1.0 where the counter counts
   core cycles, below 1 on x86 when the core runs faster than the TSC. */
static double clock_ratio(uint64_t adds) {{
    uint64_t x = 0, n = adds / 64;
    if (!n) return 0;
    uint64_t t0 = cycles();
    __asm__ __volatile__ (
{probe_body}
        : "+r"(x), "+r"(n) :: "cc"
    );
    uint64_t t1 = cycles();
    __asm__ __volatile__("" :: "r"(x));
    return (double)(t1 - t0) / (double)(adds / 64 * 64);
}}

int main(int argc, char **argv) {{
    size_t chain_bytes = argc > 1 ? strtoull(argv[1], 0, 0) : ({default_bytes}ULL);
    uint64_t iters      = argc > 2 ? strtoull(argv[2], 0, 0) : {default_iters}ULL;
    int reps            = argc > 3 ? atoi(argv[3]) : {default_reps};
    uint64_t probe_adds = argc > 4 ? strtoull(argv[4], 0, 0) : {default_probe_adds}ULL;
    uint32_t seed       = argc > 5 ? (uint32_t)strtoul(argv[5], 0, 0) : 0;
    /* each seed gives an independent pair of chains */
    uint32_t salt = seed * 0x9E3779B9u;
    void *p0 = build_chain(chain_bytes, 0x1234 ^ salt);
    void *p1 = build_chain(chain_bytes, 0x5678 ^ salt);
    uint64_t scratch[16] = {{0}};
    double *cpi = malloc(reps * sizeof(double));
    double best = 1e30;
    if (probe_adds) printf("clock_ratio_pre %.4f\n", clock_ratio(probe_adds));
    /* the chase continues across reps: restarting at p0/p1 would hit lines the
       previous rep cached. run_args() refuses a chain that reps*iters*depth wraps. */
    void *a = p0, *b = p1;
    for (int r = 0; r < reps; r++) {{
        uint64_t n = iters;
        uint64_t t0 = cycles();
        __asm__ __volatile__ (
{asm_body}
            : "+r"(a), "+r"(b), "+r"(n)
            : "r"(scratch)
            : "memory", "cc"{clobbers}
        );
        uint64_t t1 = cycles();
        cpi[r] = (double)(t1 - t0) / (double)iters;
        if (cpi[r] < best) best = cpi[r];
        /* keep the chase results alive */
        __asm__ __volatile__("" :: "r"(a), "r"(b));
    }}
    /* printed after the loop so the reps run back to back */
    for (int r = 0; r < reps; r++) printf("rep %d cycles_per_iter %.3f\n", r, cpi[r]);
    if (probe_adds) printf("clock_ratio_post %.4f\n", clock_ratio(probe_adds));
    printf("cycles_per_iter %.3f\n", best);   /* minimum over reps, for old readers */
    return 0;
}}
"""


class Emitter:
    name = "base"
    line = 64  # chain node spacing in bytes (M1 lines are 128 B)
    default_bytes = 64 << 20
    default_iters = 20000
    default_reps = 5
    default_probe_adds = 1 << 20
    cycle_counter_c = ""
    clobbers: list = []

    # operand names inside the asm block: %0 = chain a, %1 = chain b,
    # %2 = loop counter, %3 = scratch buffer address
    def miss(self, chain: int) -> str:
        raise NotImplementedError

    # A filler may expand to several lines joined by "\\n\\t" (x86 cmp + jne).
    # Local labels: the loop uses 1:, fillers use 3:.
    def filler(self, op: Op, idx: int) -> str:
        raise NotImplementedError

    def loop_head(self) -> str:
        raise NotImplementedError

    def loop_tail(self) -> str:
        raise NotImplementedError

    # clock probe: %0 = accumulator, %1 = block counter
    def probe_add(self) -> str:
        raise NotImplementedError

    def probe_tail(self) -> list:
        raise NotImplementedError

    def delay(self, op: Op, chain: int) -> str:
        """One link of the ALU delay chain `chain` (Op.DELAY_FP / DELAY_INT)."""
        raise NotImplementedError

    def lower(self, k: Kernel) -> list:
        lines = list(self.loop_head())
        for ins in k.body:
            if ins.op == Op.MISS_LOAD:
                lines.append(self.miss(ins.arg))
            elif ins.op in (Op.DELAY_FP, Op.DELAY_INT):
                lines.append(self.delay(ins.op, ins.arg))
            else:
                lines.append(self.filler(ins.op, ins.arg))
        lines += list(self.loop_tail())
        return lines


def _asm(lines):
    return "\n".join(f'            "{line}\\n\\t"' for line in lines)


def emit_c(k: Kernel, em: Emitter, **overrides) -> str:
    """C source for `k`; overrides (chain_bytes, iters, reps, probe_adds) set the argv defaults."""
    clob = "".join(f', "{c}"' for c in em.clobbers)
    return C_TEMPLATE.format(
        name=k.name,
        cycle_counter=em.cycle_counter_c,
        line=em.line,
        default_bytes=overrides.get("chain_bytes", em.default_bytes),
        default_iters=overrides.get("iters", em.default_iters),
        default_reps=overrides.get("reps", em.default_reps),
        default_probe_adds=overrides.get("probe_adds", em.default_probe_adds),
        probe_body=_asm(["1:"] + [em.probe_add()] * 64 + list(em.probe_tail())),
        asm_body=_asm(em.lower(k)),
        clobbers=clob,
    )


def run_args(
    em: Emitter, k: Kernel, chain_bytes=None, iters=None, reps=None, probe_adds=None, seed=0
) -> list:
    """argv for a generated binary; refuses a chain the reps would wrap (a wrapped
    chase revisits lines the earlier reps cached)."""
    chain_bytes = chain_bytes or em.default_bytes
    iters = iters or em.default_iters
    reps = reps or em.default_reps
    probe_adds = em.default_probe_adds if probe_adds is None else probe_adds
    nodes = chain_bytes // em.line
    used = reps * iters * k.params.get("depth", 1)
    if k.params.get("delay", "miss") == "miss" and used >= nodes:  # ALU delays chase nothing
        raise ValueError(
            f"{k.name}: {reps} reps x {iters} iters x depth "
            f"{k.params.get('depth', 1)} = {used} nodes wraps a {nodes}-node chain"
        )
    return [str(chain_bytes), str(iters), str(reps), str(probe_adds), str(seed)]


def parse_output(out: str) -> RunResult:
    """Per-rep cycles and clock probe; old binaries print only the minimum."""
    reps = [float(v) for v in re.findall(r"^rep \d+ cycles_per_iter ([\d.]+)", out, re.M)]
    if not reps:
        m = re.search(r"^cycles_per_iter ([\d.]+)", out, re.M)
        if not m:
            raise ValueError(f"no cycles_per_iter in output:\n{out[-2000:]}")
        reps = [float(m.group(1))]
    ratio = {
        w: float(m.group(1)) if (m := re.search(rf"^clock_ratio_{w} ([\d.]+)", out, re.M)) else None
        for w in ("pre", "post")
    }
    return RunResult(reps, ratio["pre"], ratio["post"])
